package org.dextur.reputation.storage;
import java.nio.file.*;
import java.util.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.policy.AdministrationData.Type;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.dextur.reputation.storage.RecoveryFixtures.*;
class LocalPolicyTest {
    @org.junit.jupiter.api.io.TempDir Path directory;
    static java.util.stream.Stream<Arguments> scenarios(){return Arrays.stream(new StorageType[]{StorageType.JSON,StorageType.SQLITE}).flatMap(type->Arrays.stream(PolicyContract.Scenario.values()).map(scenario->Arguments.of(type,scenario)));}
    @ParameterizedTest @MethodSource("scenarios")void equivalentContracts(StorageType type,PolicyContract.Scenario scenario)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){PolicyContract.run(scenario,b,directory);}}
    @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void restartAndMigrationPreserveCompletePhaseFiveAndAdministration(StorageType type)throws Exception{StorageFixtures.resources(directory);Files.writeString(directory.resolve("storage.yml"),StorageFixtures.config(type));Files.writeString(directory.resolve("target.yml"),StorageFixtures.config(type==StorageType.JSON?StorageType.SQLITE:StorageType.JSON));StorageSnapshot before;try(var b=StorageManager.create(directory,Settings.load(directory),Map.of(),false)){PolicyContract.run(PolicyContract.Scenario.SEMANTICS,b,directory);b.administer(PolicyContract.admin(PLAYER,Type.LOCK,0,NOW.plusSeconds(200)));before=b.snapshot();}try(var b=StorageManager.create(directory,Settings.load(directory),Map.of(),false)){assertEquals(before,b.snapshot());}new StorageMigration().migrate(directory,directory.resolve("target.yml"),directory.resolve("backups"),Map.of());try(var b=StorageManager.create(directory,Settings.load(directory),Map.of(),false)){assertEquals(before,b.snapshot());assertTrue(b.snapshot().administration().get(PLAYER,"global").votingLocked());}}
    @Test void sqliteFailureRollsBackLedgerProfileAndTier()throws Exception{try(var b=SqlStorage.sqlite(directory.resolve("test.sqlite"),250,false)){seed(b,directory,rules(org.dextur.reputation.domain.recovery.RecoveryRules.Type.ACTIVE_PLAYTIME));PolicyContract.configured(b,directory);var before=b.snapshot();try(var c=b.connect();var s=c.createStatement()){s.execute("CREATE TRIGGER admin_failure BEFORE INSERT ON dr_administration BEGIN SELECT RAISE(FAIL,'simulated'); END");}assertThrows(Exception.class,()->b.administer(PolicyContract.admin(PLAYER,Type.SET,100,NOW.plusSeconds(100))));assertEquals(before,b.snapshot());}}
    @ParameterizedTest @EnumSource(JsonStorage.Point.class)void jsonCrashHasCompletePreviousOrNewGeneration(JsonStorage.Point point)throws Exception{var armed=new java.util.concurrent.atomic.AtomicBoolean();StorageSnapshot before;Path json=directory.resolve("json");try(var b=new JsonStorage(json,1048576,false,p->{if(armed.get()&&p==point)throw new java.io.IOException("simulated");})){seed(b,directory,rules(org.dextur.reputation.domain.recovery.RecoveryRules.Type.ACTIVE_PLAYTIME));PolicyContract.configured(b,directory);before=b.snapshot();armed.set(true);assertThrows(Exception.class,()->b.administer(PolicyContract.admin(PLAYER,Type.SET,100,NOW.plusSeconds(100))));}try(var b=new JsonStorage(json,1048576,false)){if(point==JsonStorage.Point.AFTER_RENAME){assertEquals(100,b.getOrCreate(PLAYER,"global").visibleScore());assertEquals(1,b.snapshot().administration().get(PLAYER,"global").audit().size());assertEquals(b.getOrCreate(PLAYER,"global").tier(),b.snapshot().tiers().get(PLAYER,"global").tier());}else assertEquals(before,b.snapshot());}}
    @Test void corruptionBlocksJsonAndSqliteStartup()throws Exception{for(var type:List.of(StorageType.JSON,StorageType.SQLITE)){try(var b=StorageFixtures.local(directory,type,false)){PolicyContract.run(PolicyContract.Scenario.OVERRIDES,b,directory);if(type==StorageType.SQLITE)try(var c=((SqlStorage)b).connect();var s=c.createStatement()){s.executeUpdate("UPDATE dr_administration SET revision=revision+1");}}if(type==StorageType.JSON){Path file=directory.resolve("json/state.json");Files.writeString(file,Files.readString(file).replace("test reason","tampered"));}assertThrows(Exception.class,()->StorageFixtures.local(directory,type,false));}}
}
